/**
 * Launch-route dist guard + readiness probe regression tests.
 *
 * Builds on #804 (launch-path-smoke) and #791 (prod-route-build-regression)
 * by adding three layers of coverage for the testnet boot path:
 *
 *  1. Dist-shim existence — the tsc local build must emit .cjs shims for the
 *     JS-only route files that enhanced_unified_api_optimized loads at runtime.
 *     These shims are generated by copy-build-assets.mjs; verifying them here
 *     catches a safeMount silently failing because its .cjs peer is missing
 *     from dist/server/routes/.  (The Docker esbuild path bundles inline, so
 *     it doesn't need shims — this guard is for the local-dev / tsc path.)
 *
 *  2. Entrypoint references — enhanced_unified_api_optimized.ts must reference
 *     all five launch-critical paths: /api/wallet, /api/oracle, /api/weather,
 *     and the operational-probes router at /api (which exposes /api/ready and
 *     /api/live).
 *
 *  3. Readiness + liveness HTTP semantics — exercised via supertest against
 *     the createEnhancedApiOperationalProbes factory:
 *       • /api/ready  → 503 when the cache / DB is unhealthy ("503 w/o DB")
 *       • /api/ready  → 200 when all deps are healthy
 *       • /api/live   → 200 regardless of dependency state (liveness invariant)
 *
 * The .cjs→.js jest.config.cjs moduleNameMapper is required for tests that
 * import server modules which in turn import dist-only .cjs shims.  Without
 * that mapper, jest cannot locate create-health-middleware.cjs from the source
 * tree and all probe tests fail with a module-not-found error.
 *
 * Closes #715 (regression context); extends #804 / #791.
 */

import { beforeAll, beforeEach, describe, expect, it, jest } from '@jest/globals';
import { execSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import express from 'express';
import request from 'supertest';

const repoRoot = path.resolve(__dirname, '..');
const distRoutes = path.join(repoRoot, 'dist', 'server', 'routes');
const entrypointPath = path.join(
  repoRoot,
  'server',
  'enhanced_unified_api_optimized.ts',
);
const buildOutput = path.join(repoRoot, 'dist', 'server', 'enhanced_unified_api_optimized.js');
const copyBuildAssets = path.join(repoRoot, 'scripts', 'copy-build-assets.mjs');

beforeAll(() => {
  if (!existsSync(distRoutes) || !existsSync(buildOutput)) {
    execSync('npm run build', { cwd: repoRoot, stdio: 'pipe' });
    execSync(`node ${copyBuildAssets}`, { cwd: repoRoot, stdio: 'pipe' });
  }
});

// ─── 1. Dist shim existence ────────────────────────────────────────────────
//
// These .cjs files are the runtime modules that safeMount() require()s inside
// the tsc-built dist tree.  Missing → the route is silently dropped at boot
// (safeMount swallows the error) and the endpoint returns 404.

describe('launch-route dist shims — tsc build output guard', () => {
  it.each([
    ['wallet-routes', '/api/wallet'],
    ['oracle-routes', '/api/oracle'],
    ['oracle-detail-routes', '/api/oracle (detail sub-router)'],
    ['weather-routes', '/api/weather'],
  ])(
    'dist/server/routes/%s.cjs exists (required for safeMount at %s)',
    (moduleName) => {
      expect(
        existsSync(path.join(distRoutes, `${moduleName}.cjs`)),
      ).toBe(true);
    },
  );
});

// ─── 2. Entrypoint references all five launch-critical paths ──────────────

describe('launch-route entrypoint references — enhanced_unified_api_optimized.ts', () => {
  let source: string;

  beforeEach(() => {
    source = readFileSync(entrypointPath, 'utf8');
  });

  it.each([
    ['/api/wallet', "safeMount('/api/wallet'"],
    ['/api/oracle', "safeMount('/api/oracle'"],
    ['/api/weather', "safeMount('/api/weather'"],
  ])('safeMount(%s) is present in the entrypoint', (_path, needle) => {
    expect(source).toContain(needle);
  });

  it('operational-probes router is mounted at /api (exposes /api/ready and /api/live)', () => {
    // The probes router is mounted via app.use('/api', createEnhancedApiOperationalProbes(...).router)
    // which registers /api/ready (readiness) and /api/live (liveness).
    expect(source).toContain("'/api'");
    expect(source).toContain('createEnhancedApiOperationalProbes');
  });
});

// ─── 3a. Readiness probe (/api/ready) HTTP semantics ─────────────────────
//
// /api/ready is the k8s-style readiness gate (also called /readyz in infra
// configs).  It MUST return 503 whenever a critical dependency is unhealthy
// so that the load balancer stops routing traffic, and 200 only when the
// service is genuinely ready to accept requests.

describe('readiness probe (/api/ready) — correct HTTP status under dependency failures', () => {
  let createEnhancedApiOperationalProbes: any;

  beforeEach(() => {
    jest.resetModules();
    ({ createEnhancedApiOperationalProbes } = require(
      '../server/enhanced_unified_api_operational_probes',
    ));
  });

  function makeApp(cacheStatus: string) {
    const probes = createEnhancedApiOperationalProbes({
      state: { draining: false },
      getCacheHealthStatus: async () => ({ status: cacheStatus }),
    });
    const app = express();
    app.use('/api', probes.router);
    return app;
  }

  it('returns 200 when cache / DB layer is healthy', async () => {
    const res = await request(makeApp('healthy')).get('/api/ready');
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('ready');
  });

  it('returns 503 when cache / DB layer is down — traffic must be gated (503 w/o DB)', async () => {
    const res = await request(makeApp('down')).get('/api/ready');
    expect(res.status).toBe(503);
    expect(res.body.status).toBe('not_ready');
  });

  it('returns 503 when cache / DB is degraded — partial outage gates traffic', async () => {
    const res = await request(makeApp('degraded')).get('/api/ready');
    expect(res.status).toBe(503);
    expect(res.body.status).toBe('not_ready');
  });

  it('returns 503 while draining — shutting-down instance must not receive new traffic', async () => {
    const probes = createEnhancedApiOperationalProbes({
      state: { draining: true },
      getCacheHealthStatus: async () => ({ status: 'healthy' }),
    });
    const app = express();
    app.use('/api', probes.router);
    const res = await request(app).get('/api/ready');
    expect(res.status).toBe(503);
    expect(res.body.status).toBe('not_ready');
  });

  it('returns 503 when core4 /readyz is unreachable (chain not ready)', async () => {
    const probes = createEnhancedApiOperationalProbes({
      state: { draining: false },
      getCacheHealthStatus: async () => ({ status: 'healthy' }),
      probeCore4Readiness: async () => ({
        status: 'down',
        readinessStatus: 'not_ready',
        reachable: false,
        lastError: 'connect ECONNREFUSED',
      }),
    });
    const app = express();
    app.use('/api', probes.router);
    const res = await request(app).get('/api/ready');
    expect(res.status).toBe(503);
    expect(res.body.status).toBe('not_ready');
  });

  it('returns 503 when required safeMount entries are missing', async () => {
    const probes = createEnhancedApiOperationalProbes({
      state: { draining: false },
      getCacheHealthStatus: async () => ({ status: 'healthy' }),
      probeCore4Readiness: async () => ({ status: 'up', readinessStatus: 'ready' }),
      safeMountReadiness: {
        requiredMissing: [
          {
            mountPath: '/api/modules',
            modulePath: './routes/module-controller-routes',
            reason: 'MODULE_NOT_FOUND',
          },
        ],
        optionalMissing: [],
      },
    });
    const app = express();
    app.use('/api', probes.router);
    const res = await request(app).get('/api/ready');
    expect(res.status).toBe(503);
    expect(res.body.status).toBe('not_ready');
    expect(res.body.dependencies.safeMounts.status).toBe('down');
    expect(Array.isArray(res.body.dependencies.safeMounts.requiredMissing)).toBe(true);
  });

  it('returns 200 when only optional safeMount entries are missing', async () => {
    const probes = createEnhancedApiOperationalProbes({
      state: { draining: false },
      getCacheHealthStatus: async () => ({ status: 'healthy' }),
      probeCore4Readiness: async () => ({ status: 'up', readinessStatus: 'ready' }),
      safeMountReadiness: {
        requiredMissing: [],
        optionalMissing: [
          {
            mountPath: '/api/n8n',
            modulePath: './routes/n8n-routes',
            reason: 'OPTIONAL_TIMEOUT',
          },
        ],
      },
    });
    const app = express();
    app.use('/api', probes.router);
    const res = await request(app).get('/api/ready');
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('ready');
    expect(res.body.dependencies.safeMounts.status).toBe('degraded');
    expect(res.body.dependencies.safeMounts.requiredMissing).toEqual([]);
  });
});

// ─── 3b. Liveness probe (/api/live) — always 200 ─────────────────────────
//
// /api/live is the k8s liveness probe.  It must always return 200 as long as
// the process is alive; it must NEVER depend on backend dependencies (DB, Redis,
// core4) so that a not-ready state doesn't trigger a container restart loop.

describe('liveness probe (/api/live) — invariant: always 200 regardless of deps', () => {
  let createEnhancedApiOperationalProbes: any;

  beforeEach(() => {
    jest.resetModules();
    ({ createEnhancedApiOperationalProbes } = require(
      '../server/enhanced_unified_api_operational_probes',
    ));
  });

  function makeApp(cacheStatus: string) {
    const probes = createEnhancedApiOperationalProbes({
      state: { draining: false },
      getCacheHealthStatus: async () => ({ status: cacheStatus }),
    });
    const app = express();
    app.use('/api', probes.router);
    return app;
  }

  it('returns 200 when cache is healthy', async () => {
    const res = await request(makeApp('healthy')).get('/api/live');
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('alive');
  });

  it('returns 200 even when cache / DB is down (liveness independent of deps)', async () => {
    const res = await request(makeApp('down')).get('/api/live');
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('alive');
  });

  it('returns 200 even when core4 chain is not ready (no restart loop)', async () => {
    const probes = createEnhancedApiOperationalProbes({
      state: { draining: false },
      getCacheHealthStatus: async () => ({ status: 'healthy' }),
      probeCore4Readiness: async () => ({
        status: 'down',
        readinessStatus: 'not_ready',
        reachable: false,
      }),
    });
    const app = express();
    app.use('/api', probes.router);
    const res = await request(app).get('/api/live');
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('alive');
  });

  it('returns 200 even while draining (process alive during graceful shutdown)', async () => {
    const probes = createEnhancedApiOperationalProbes({
      state: { draining: true },
      getCacheHealthStatus: async () => ({ status: 'down' }),
    });
    const app = express();
    app.use('/api', probes.router);
    const res = await request(app).get('/api/live');
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('alive');
  });
});
